/**
 * The workspace's temp-HOME test wrapper (SW-124). Every test command and
 * subagent brief runs through one generated script, so no session has to
 * hand-roll `HOME=$(mktemp -d) …` and none can forget it.
 */

import * as fs from "node:fs";
import * as path from "node:path";

import { dotDir } from "./dot_dir.js";

const SCRIPT = `#!/bin/sh
# Generated by \`werkmeister init-workspace\` (SW-124); rerun it to regenerate.
# Runs <cmd...> with HOME set to a fresh temporary directory, removed on exit,
# so no test or CLI exercise reads or writes the real ~/.werkmeister.
[ "$#" -gt 0 ] || { echo "usage: with-temp-home <cmd> [args...]" >&2; exit 2; }
tmp=$(mktemp -d) || exit 1
trap 'rm -rf "$tmp"' EXIT
trap 'exit 130' HUP INT TERM
# Corepack keeps pnpm under HOME; without this a fresh HOME re-downloads it every run.
export COREPACK_HOME="\${COREPACK_HOME:-$HOME/.cache/node/corepack}"
HOME=$tmp "$@"
`;

export function tempHomeWrapper(workspaceRoot: string): string {
  return path.join(dotDir(workspaceRoot), "bin", "with-temp-home");
}

/** Write the wrapper, executable, over any earlier copy; returns its path. */
export function writeTempHomeWrapper(workspaceRoot: string): string {
  const target = tempHomeWrapper(workspaceRoot);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, SCRIPT);
  // writeFileSync's mode applies only to a file it creates.
  fs.chmodSync(target, 0o755);
  return target;
}
